def decode(value):
    return (value.replace('@LT@', chr(60)).replace('@GT@', chr(62))
            .replace('@AMP@', chr(38)).replace('@MDASH@', chr(8212)))


def require(ok, message):
    if not ok:
        raise RuntimeError(message)


def normalize(raw, name):
    text = raw.decode('utf-8')
    normalized = text.replace('\r\n', '\n')
    require('\r' not in normalized, name + ': bare CR is unsupported')
    crlf = '\r\n' in text
    require(not crlf or '\n' not in text.replace('\r\n', ''), name + ': mixed LF/CRLF')
    return normalized, crlf


def backend_checks(source, directory):
    tree = ast.parse(source)
    values = {}
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id in ('TASK_STUDY_MAP', 'JOURNEY_MAP', 'REVERSE_MODES'):
                    require(target.id not in values, 'duplicate definition: ' + target.id)
                    values[target.id] = ast.literal_eval(node.value)
    require(set(values) == {'TASK_STUDY_MAP', 'JOURNEY_MAP', 'REVERSE_MODES'}, 'missing map or registry')
    mapping = values['TASK_STUDY_MAP']
    tasks = [task['id'] for phase in values['JOURNEY_MAP'].values() for task in phase['tasks']]
    require(len(mapping) == 18 and len(tasks) == 18 and len(set(tasks)) == 18, 'expected eighteen unique tasks')
    require(set(mapping) == set(tasks), 'task routing map must cover the exact journey task IDs')
    for task, entry in mapping.items():
        require(set(entry) == {'mode', 'tool'}, task + ': unexpected mapping keys')
        require(entry['mode'] in values['REVERSE_MODES'], task + ': unknown study choice')
        require(entry['tool'] in ('dna', 'funnel', 'content', 'dm', 'community', None), task + ': unknown tool')
    handlers = [n for n in tree.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name == 'get_journey_status']
    require(len(handlers) == 1, 'journey handler must be unique')
    exposed = 0
    for node in ast.walk(handlers[0]):
        if isinstance(node, ast.Return) and isinstance(node.value, ast.Dict):
            for key, value in zip(node.value.keys, node.value.values):
                if isinstance(key, ast.Constant) and key.value == 'task_study_map':
                    require(isinstance(value, ast.Name) and value.id == 'TASK_STUDY_MAP', 'unexpected journey map exposure')
                    exposed += 1
    require(exposed == 1, 'journey must expose the routing map exactly once')
    path = directory / 'main.py'
    path.write_text(source, encoding='utf-8')
    py_compile.compile(str(path), cfile=str(directory / 'main.pyc'), doraise=True)
    print('  PASS: eighteen task routes, registry/tool validation, journey exposure, py_compile')


def node_checks(html, directory):
    node = shutil.which('node')
    require(node is not None, 'Node.js is required; nothing was written')
    lt, gt = chr(60), chr(62)
    pattern = lt + r'script\b([^' + gt + r']*)' + gt + r'(.*?)' + lt + r'/script\s*' + gt
    checked = 0
    for index, (attrs, source) in enumerate(re.findall(pattern, html, re.S | re.I)):
        if re.search(r'\bsrc\s*=', attrs, re.I):
            continue
        kind = re.search(r'''\btype\s*=\s*["']([^"']+)["']''', attrs, re.I)
        if kind and kind.group(1).lower() not in ('text/javascript', 'application/javascript', 'module'):
            continue
        path = directory / ('inline-' + str(index) + '.js')
        path.write_text(source, encoding='utf-8')
        result = subprocess.run([node, '--check', str(path)], capture_output=True, text=True, timeout=60)
        require(result.returncode == 0, 'node --check failed: ' + result.stderr[-2500:])
        checked += 1
    require(checked != 0, 'no inline JavaScript found')
    print('  PASS: node --check on every full inline script')
    candidate = directory / 'chat_test.html'
    candidate.write_text(html, encoding='utf-8')
    for name, encoded in [('K.2 regression', K2_TEST_ENCODED), ('K.3 offline', K3_TEST_ENCODED)]:
        suite = directory / (name.replace(' ', '_') + '.js')
        suite.write_text(decode(encoded), encoding='utf-8')
        result = subprocess.run([node, str(suite), str(candidate)], capture_output=True, text=True, timeout=120)
        require(result.returncode == 0, name + ' tests failed:\n' + result.stdout[-2000:] + result.stderr[-2500:])
        print(result.stdout.rstrip())


def stage(path, payload, mode):
    fd, temp = tempfile.mkstemp(prefix='.brickK3-', dir=str(path.parent))
    try:
        with os.fdopen(fd, 'wb') as stream:
            stream.write(payload)
            os.fchmod(stream.fileno(), mode)
            stream.flush()
            os.fsync(stream.fileno())
        return Path(temp)
    except BaseException:
        if os.path.exists(temp):
            os.unlink(temp)
        raise


def fsync_directory(path):
    fd = os.open(str(path), os.O_RDONLY | getattr(os, 'O_DIRECTORY', 0))
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def replace_pair(paths, payloads, originals, modes):
    staged = {}
    main_written = False
    try:
        for name, path in paths.items():
            staged[name] = stage(path, payloads[name], modes[name])
        os.replace(staged['main.py'], paths['main.py'])
        main_written = True
        try:
            os.replace(staged['chat_test.html'], paths['chat_test.html'])
        except BaseException as error:
            restore = stage(paths['main.py'], originals['main.py'], modes['main.py'])
            try:
                os.replace(restore, paths['main.py'])
                fsync_directory(paths['main.py'].parent)
                main_written = False
            finally:
                if restore.exists():
                    restore.unlink()
            raise RuntimeError('HTML replacement failed; main.py was restored. Backups retained.') from error
        fsync_directory(paths['main.py'].parent)
    except BaseException:
        if main_written and paths['chat_test.html'].read_bytes() == originals['chat_test.html']:
            print('WARNING: inspect both files and retained backups before retrying.', file=sys.stderr)
        raise
    finally:
        for temp in staged.values():
            if temp.exists():
                temp.unlink()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--dir', default='.', help='folder containing main.py and chat_test.html')
    parser.add_argument('--dry-run', action='store_true')
    args = parser.parse_args()
    root = Path(args.dir).resolve()
    names = ('main.py', 'chat_test.html')
    paths = {name: root / name for name in names}
    for name, path in paths.items():
        require(path.is_file() and not path.is_symlink(), name + ' must be a regular non-symlink file')
    raw = {name: path.read_bytes() for name, path in paths.items()}
    normalized = {name: normalize(raw[name], name) for name in names}
    text = {name: normalized[name][0] for name in names}
    require('BRICK K.2' in text['chat_test.html'], 'BRICK K.2 is required in chat_test.html')
    require('BRICK K.1.5' in text['main.py'], 'BRICK K.1.5 is required in main.py')
    for name in names:
        require(MARKER not in text[name], MARKER + ' already present in ' + name + '; refusing second run')
    backups = {name: path.with_name(path.name + '.bak-brickK3') for name, path in paths.items()}
    for backup in backups.values():
        require(not os.path.lexists(backup), str(backup) + ' already exists; never overwritten')
    anchors = [(name, target, decode(old), decode(new), expected) for name, target, old, new, expected in ANCHORS_ENCODED]
    print('Targets: main.py and chat_test.html only')
    for name, target, old, new, expected in anchors:
        count = text[target].count(old)
        print('  %s (%s): found %d, expected %d' % (name, target, count, expected))
        require(count == expected, name + ': exact anchor count mismatch')
    output = dict(text)
    for name, target, old, new, expected in anchors:
        output[target] = output[target].replace(old, new, expected)
    restored = dict(output)
    for name, target, old, new, expected in reversed(anchors):
        require(restored[target].count(new) == expected, name + ': replacement is not unique')
        restored[target] = restored[target].replace(new, old, expected)
    require(restored == text, 'edit footprint differs from approved insertions')
    with tempfile.TemporaryDirectory(prefix='k3-checks-') as directory:
        backend_checks(output['main.py'], Path(directory))
        node_checks(output['chat_test.html'], Path(directory))
    if args.dry_run:
        print('DRY RUN PASS: no target or backup written')
        return
    modes = {name: stat.S_IMODE(path.stat().st_mode) for name, path in paths.items()}
    payloads = {name: (output[name].replace('\n', '\r\n') if normalized[name][1] else output[name]).encode('utf-8') for name in names}
    for name in names:
        require(paths[name].read_bytes() == raw[name], name + ' changed during validation; refusing write')
        require(not paths[name].is_symlink(), name + ' became a symlink')
        require(not os.path.lexists(backups[name]), str(backups[name]) + ' appeared during validation')
    for name, backup in backups.items():
        with open(backup, 'xb') as stream:
            stream.write(raw[name])
            os.fchmod(stream.fileno(), modes[name])
            stream.flush()
            os.fsync(stream.fileno())
    fsync_directory(root)
    for name in names:
        require(paths[name].read_bytes() == raw[name], name + ' changed after backup; refusing write')
    replace_pair(paths, payloads, raw, modes)
    for name in names:
        require(paths[name].read_bytes() == payloads[name], name + ': post-write verification failed')
        print('APPLIED: ' + str(paths[name]))
        print('BACKUP: ' + str(backups[name]))
    print('Rebuild your Docker image if it uses COPY . .; hard-refresh the browser.')


if __name__ == '__main__':
    try:
        main()
    except (OSError, UnicodeError, RuntimeError, SyntaxError, ValueError, py_compile.PyCompileError, subprocess.TimeoutExpired) as error:
        print('ABORT: ' + str(error), file=sys.stderr)
        print('Apply was not confirmed. Inspect any retained .bak-brickK3 backups.', file=sys.stderr)
        sys.exit(1)
